import React from 'react';
import { AbsoluteFill, interpolate, useCurrentFrame } from 'remotion';
import { COLORS, EASINGS } from '../../brand';
import { FONT_BODY, FONT_MONO } from '../../fonts';
import { CLAMP } from '../../lib/kit';
import { CaptionTrack, CoverImage, HookTitle, ProgressBar, SAFE, ShortBg, ToolCard, Watermark, secToFrame } from '../../lib/shorts';
import { WORDS } from './words';

// short-119: generated by the daily batch. Cover held at frame 0; closes on the cover.
export const compositionConfig = { id: 'Short119', durationInSeconds: 37.7, fps: 30, width: 1080, height: 1920 };

const B1 = secToFrame(3.0);
const B2 = secToFrame(5.3);
const B3 = secToFrame(12.1);
const B4 = secToFrame(14.0);
const B5 = secToFrame(19.5);
const B6 = secToFrame(24.7);
const B7 = secToFrame(28.1);
const CTA = secToFrame(34.8);

const FadeOut: React.FC<{ at: number; children: React.ReactNode }> = ({ at, children }) => {
  const frame = useCurrentFrame();
  const op = 1 - interpolate(frame, [at - 8, at + 2], [0, 1], { ...CLAMP, easing: EASINGS.easeIn });
  return <AbsoluteFill style={{ opacity: op }}>{children}</AbsoluteFill>;
};

const Line: React.FC<{ k: string; v: string; good?: boolean; bad?: boolean }> = ({ k, v, good, bad }) => (
  <div style={{ display: 'flex', justifyContent: 'space-between', fontFamily: FONT_MONO, fontSize: 32 }}>
    <span style={{ color: COLORS.d400 }}>{k}</span>
    <span style={{ color: bad ? COLORS.danger : good ? COLORS.signalAlt : COLORS.d300, fontWeight: good || bad ? 700 : 400 }}>{v}</span>
  </div>
);
const Panel: React.FC<{ children: React.ReactNode }> = ({ children }) => (
  <div style={{ background: COLORS.d900, borderRadius: 12, padding: '24px 26px', display: 'flex', flexDirection: 'column', gap: 16 }}>{children}</div>
);

const Short119: React.FC = () => {
  const frame = useCurrentFrame();
  const ctaOp = interpolate(frame, [CTA, CTA + 12], [0, 1], { ...CLAMP, easing: EASINGS.easeOut });
  const lines = [{ text: 'SAME PRICE' }, { text: 'HALF THE CACHE', accent: true }];
  return (
    <AbsoluteFill>
      <ShortBg />
      <FadeOut at={B1}>
        <CoverImage src="projects/short-119/cover.png" out={B1 - 10} />
        <HookTitle hold onDark kicker="SONNET 5.5 + SOL 6.1" lines={lines} />
      </FadeOut>
      <FadeOut at={B2}>
        <ToolCard name="Claude Sonnet 5.5" tagline="Same list price." chip="$2 / $10" at={B1 - 2}None>
          <Panel>
            <Line k="input /1M" v="$2.00" />
            <Line k="output /1M" v="$10.00" />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={B3}>
        <ToolCard name="GPT-6.1 Sol" tagline="Same list price." chip="$2 / $10" at={B2 - 2}None>
          <Panel>
            <Line k="input /1M" v="$2.00" />
            <Line k="output /1M" v="$10.00" />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={B4}>
        <ToolCard name="Cached input" tagline="Look closer." chip="CACHE HITS" at={B3 - 2} chipColor={COLORS.accent2}>
          <Panel>
            <Line k="repeat prompts" v="billed here" />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={B5}>
        <ToolCard name="Sonnet cache hit" tagline="Per million tokens." chip="$0.20 > $0.10" at={B4 - 2}None>
          <Panel>
            <Line k="Sonnet 5" v="$0.20" bad />
            <Line k="Sonnet 5.5" v="$0.10" good />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={B6}>
        <ToolCard name="Sol cache hit" tagline="Per million tokens." chip="$0.20 > $0.10" at={B5 - 2}None>
          <Panel>
            <Line k="GPT-6 Sol" v="$0.20" bad />
            <Line k="GPT-6.1 Sol" v="$0.10" good />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={B7}>
        <ToolCard name="Both halved it" tagline="Headline price unchanged." chip="2X" at={B6 - 2} chipColor={COLORS.accent2}>
          <Panel>
            <Line k="Sonnet" v="$0.20 to $0.10" good />
            <Line k="Sol" v="$0.20 to $0.10" good />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={CTA}>
        <ToolCard name="Repeat long prompts?" tagline="Check your model version." chip="CACHE BILL" at={B7 - 2} chipColor={COLORS.accent2}>
          <Panel>
            <Line k="old version" v="$0.20" bad />
            <Line k="new version" v="$0.10" good />
          </Panel>
        </ToolCard>
      </FadeOut>
      <AbsoluteFill style={{ opacity: ctaOp }}>
        <CoverImage src="projects/short-119/cover.png" at={CTA} />
        <HookTitle hold onDark at={CTA} kicker="SONNET 5.5 + SOL 6.1" lines={lines} />
        <div style={{ position: 'absolute', left: SAFE.side, right: SAFE.side, top: SAFE.top + 520, textAlign: 'center', fontFamily: FONT_BODY, fontWeight: 600, fontSize: 44, color: 'rgba(255,255,255,0.82)' }}>
          Same price. Half the cache bill.
        </div>
      </AbsoluteFill>
      <CaptionTrack words={WORDS} />
      <Watermark at={12} />
      <ProgressBar />
    </AbsoluteFill>
  );
};
export default Short119;
